
const $=s=>document.querySelector(s);let scene=0;let closed=[false,false],storeClosed=false;const products=[{name:'국내산 배추',photo:'cabbage-seller.png',price:1500,stock:'7포기'},{name:'수제 두부',photo:'tofu-seller.png',price:2100,stock:'8모'}];const labels=['상품 마감 대상','상품 마감 확인','상품 마감 완료','가게 판매 상품','일괄 마감 확인','일괄 마감 완료'];function toast(t){$('.toast').textContent=t;$('.toast').classList.remove('hidden');setTimeout(()=>$('.toast').classList.add('hidden'),2200)}function go(n){scene=n;render()}function action(t,fn,danger=false){$('#action').innerHTML=`<button class="primary ${danger?'danger':''}">${t}</button>`;$('#action button').onclick=fn;$('#content').classList.add('has-action')}function row(i){const p=products[i];return `<button class="product-row ${closed[i]?'is-closed':''}" data-product="${i}"><img src="assets/${p.photo}" alt="${p.name}"><div><h3>${p.name}</h3><b>${p.price.toLocaleString()}원</b><p>남은 수량 ${p.stock}</p></div><span>${closed[i]?'판매 종료':'판매 중'}</span></button>`}function store(){return `<p class="eyebrow">서원시장 · 판매자</p><h1>홍길네 채소가게</h1><dl class="store-meta"><dt>영업시간</dt><dd>09:00–19:00</dd><dt>연락처</dt><dd>점포에 등록된 연락처</dd><dt>위치</dt><dd>시장 동문 입구 두 번째 블록 우측</dd></dl><p class="store-intro">정직하고 저렴하게 판매하겠습니다.<br>방문하시면 더 다양한 상품을 만나보실 수 있어요.</p>`}function bindRows(){document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{if(+b.dataset.product===0)go(0);else toast(closed[1]?'판매가 종료된 상품입니다.':'다른 상품은 계속 판매 중이에요.')})}function confirm(bulk){const count=closed.filter(v=>!v).length;$('#layer').innerHTML=`<div class="overlay"><section class="confirm-box" role="dialog" aria-modal="true" aria-label="${bulk?'가게 일괄 마감 확인':'상품 마감 확인'}"><span class="scope-badge">${bulk?'가게 전체 상품':'선택한 상품 1개'}</span><h2>${bulk?'판매 중인 상품을<br>모두 마감할까요?':'배추 판매를<br>마감할까요?'}</h2><div class="scope-detail">${bulk?'홍길네 채소가게 · 판매 중 '+count+'개 상품':'국내산 배추 · 남은 수량 7포기'}<br>${bulk?'이 가게의 판매 중인 상품이 모두 종료돼요.':'이 상품만 종료되고, 다른 상품은 계속 판매돼요.'}</div><p>마감 후에는 손님이 해당 상품을 새로 구매할 수 없어요.</p><div class="sheet-buttons"><button class="outline" id="cancel">돌아가기</button><button class="primary danger" id="confirm">${bulk?'모두 마감하기':'상품 마감하기'}</button></div></section></div>`;$('#cancel').onclick=()=>go(bulk?3:0);$('#confirm').onclick=()=>{if(bulk){closed=[true,true];storeClosed=true;go(5)}else{closed[0]=true;go(2)}}}
function render(){const c=$('#content');c.classList.remove('has-action');$('#layer').innerHTML='';$('.head b').textContent=scene<3?'상품 관리':'가게 관리';$('.steps').innerHTML=`<span class="branch-label">개별 상품 마감</span>${labels.slice(0,3).map((t,i)=>`<button data-scene="${i}" class="${scene===i?'on':''}">0${i+1}　${t}</button>`).join('')}<span class="branch-label">가게 일괄 마감</span>${labels.slice(3).map((t,i)=>`<button data-scene="${i+3}" class="${scene===i+3?'on':''}">0${i+4}　${t}</button>`).join('')}`;document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{const n=+b.dataset.scene;if(n===2)closed[0]=true;if(n===5){closed=[true,true];storeClosed=true}if(n===0||n===1){closed=[false,false];storeClosed=false}if(n===3||n===4){closed=[false,false];storeClosed=false}go(n)});
if(scene<2){c.innerHTML=`<div class="photo-wrap"><img class="hero" src="assets/cabbage-seller.png" alt="국내산 배추 사진"></div><span class="scope-badge">개별 상품 관리</span><h1>국내산 배추</h1><div class="shop-info" style="margin-top:18px"><div><b>홍길네 채소가게</b><p>서원시장 · 09:00–19:00</p></div><span>${closed[0]?'판매 종료':'판매 중'}</span></div><div class="detail-price"><em>40%</em><b>1,500원</b><small>/ 1포기</small></div><p class="stock-line">남은 수량 7포기</p><p class="description">오늘 들어온 국내산 배추예요.<br>상품 하나만 마감할 때 이 화면을 이용해요.</p><div class="pickup-note">이 상품의 판매만 종료합니다.<br>다른 상품의 판매에는 영향을 주지 않아요.</div>`;action(closed[0]?'마감 결과 보기':'이 상품 마감하기',()=>closed[0]?go(2):go(1),!closed[0]);if(scene===1)confirm(false)}
if(scene===2){c.innerHTML=`<div class="result-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg></div><h1 class="result-title">배추 판매를 마감했어요</h1><p class="result-sub">선택한 상품만 판매가 종료되었어요.<br>다른 상품은 계속 판매 중입니다.</p><div class="store-heading"><h2>가게 상품 상태</h2></div>${row(0)}${row(1)}<p class="summary-inline">마감된 상품은 손님에게 판매 중으로 표시되지 않아요.</p>`;bindRows();action('가게 상품 관리로 이동',()=>go(3))}
if(scene===3||scene===4){c.innerHTML=store()+`<div class="store-heading"><h2>등록한 상품</h2><span>판매 중 ${closed.filter(v=>!v).length}개</span></div>${row(0)}${row(1)}<p class="summary-inline">일괄 마감은 이 가게의 판매 중인 상품에 적용됩니다.</p>`;bindRows();action(storeClosed?'마감 상태 확인':'판매 상품 일괄 마감',()=>go(storeClosed?5:4),!storeClosed);if(scene===4)confirm(true)}
if(scene===5){c.innerHTML=store()+`<div class="empty-state"><div class="result-icon" style="margin-top:15px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg></div><h2>상품 준비 중이에요</h2><p>판매 중이던 상품을 모두 마감했어요.<br>현재 구매할 수 있는 상품이 없습니다.</p></div><div class="status-card"><strong>가게 상품 일괄 마감 완료</strong>상품 판매가 종료된 상태입니다.<br>가게 소개와 영업시간은 그대로 유지돼요.</div>`;action('시안 다시 체험하기',()=>reset())}c.scrollTop=0}
function reset(){closed=[false,false];storeClosed=false;go(0)}$('.demo-reset').onclick=reset;$('.back').onclick=()=>go([3,0,0,0,3,3][scene]);document.querySelectorAll('.nav button').forEach((b,i)=>{b.classList.toggle('active',i===0);b.onclick=()=>i===0?go(3):toast('판매 마감 흐름을 체험하는 시안입니다.')});render();
